// Replays Tools/Parity/vectors.json (generated by the C# EditMode test ParityVectorsTests) through
// the TypeScript port. Returns a list of human-readable mismatches (empty = parity).
import type { DuelConfig } from "./config.ts";
import { beatNs } from "./config.ts";
import { evaluateDamage, gradeFromMs } from "./damage.ts";
import { NetRandom } from "./rng.ts";
import { createSchedule } from "./schedule.ts";
import { type AttemptInput, playRecordedMatch, playSingleExchange } from "./recorded_match.ts";

// deno-lint-ignore no-explicit-any
type Any = any;

const TOL = 1e-9;

function compare(path: string, expected: unknown, actual: unknown, out: string[]): void {
  if (typeof expected === "number") {
    if (typeof actual !== "number" || !(Math.abs(expected - actual) <= TOL)) {
      out.push(`${path}: expected ${expected}, got ${actual}`);
    }
    return;
  }
  if (Array.isArray(expected)) {
    if (!Array.isArray(actual) || actual.length !== expected.length) {
      out.push(`${path}: expected array[${expected.length}], got ${JSON.stringify(actual)}`);
      return;
    }
    expected.forEach((e, i) => compare(`${path}[${i}]`, e, actual[i], out));
    return;
  }
  if (expected !== null && typeof expected === "object") {
    if (actual === null || typeof actual !== "object") {
      out.push(`${path}: expected object, got ${JSON.stringify(actual)}`);
      return;
    }
    for (const k of Object.keys(expected)) {
      compare(`${path}.${k}`, (expected as Any)[k], (actual as Any)[k], out);
    }
    return;
  }
  if (expected !== actual) out.push(`${path}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
}

function attempt(x: Any): AttemptInput {
  return { kind: x.kind, reactionNs: x.reactionNs };
}

export function checkMeta(cfg: DuelConfig, v: Any): string[] {
  const out: string[] = [];
  const m = v.meta[0];
  const actual = {
    version: 1,
    tieWindowMs: cfg.tieWindowMs,
    anticipationMs: cfg.anticipationMs,
    noShotTimeoutSeconds: cfg.noShotTimeoutSeconds,
    reportSlackMs: cfg.reportSlackMs,
    commitGraceMs: cfg.commitGraceMs,
    maxHp: cfg.maxHp,
    holdMinSeconds: cfg.holdMinSeconds,
    holdMaxSeconds: cfg.holdMaxSeconds,
    countdownBeats: cfg.countdownBeats,
    beatNs: beatNs(cfg),
    suddenDeathEnabled: cfg.suddenDeathEnabled,
    suddenDeathHp: cfg.suddenDeathHp,
    suddenDeathDamageMultiplier: cfg.suddenDeathDamageMultiplier,
  };
  const { source: _s, generator: _g, ...expected } = m;
  compare("meta", expected, actual, out);
  return out;
}

export function checkSchedules(cfg: DuelConfig, v: Any): string[] {
  const out: string[] = [];
  for (const s of v.schedules) {
    let rng = new NetRandom(s.seed);
    const next = s.next.map(() => rng.next());
    rng = new NetRandom(s.seed);
    const holds: number[] = [];
    const offs: number[] = [];
    for (let i = 0; i < s.holdNs.length; i++) {
      const sc = createSchedule(cfg, rng);
      holds.push(sc.holdNs);
      offs.push(sc.cueOffsetNs);
    }
    compare(`schedules[seed=${s.seed}].next`, s.next, next, out);
    compare(`schedules[seed=${s.seed}].holdNs`, s.holdNs, holds, out);
    compare(`schedules[seed=${s.seed}].cueOffsetNs`, s.cueOffsetNs, offs, out);
  }
  return out;
}

export function checkDamage(cfg: DuelConfig, v: Any): string[] {
  const out: string[] = [];
  for (const d of v.damage) {
    compare(`damage[ms=${d.ms}]`, { damage: d.damage, grade: d.grade }, {
      damage: evaluateDamage(cfg, d.ms),
      grade: gradeFromMs(cfg, d.ms),
    }, out);
  }
  return out;
}

export function checkRounds(cfg: DuelConfig, v: Any): string[] {
  const out: string[] = [];
  for (const c of v.rounds) {
    const got = playSingleExchange(cfg, [c.hp[0], c.hp[1]], attempt(c.slots[0]), attempt(c.slots[1]));
    compare(`rounds[${c.name}]`, c.expect, got, out);
  }
  return out;
}

export function checkMatches(cfg: DuelConfig, v: Any): string[] {
  const out: string[] = [];
  for (const c of v.matches) {
    const got = playRecordedMatch(
      cfg,
      { seed: c.seed, rounds: c.rounds, maxAttempts: c.maxAttempts },
      c.a.map(attempt),
      c.b.map(attempt),
    );
    compare(`matches[${c.name}]`, c.expect, got, out);
  }
  return out;
}

export function checkAll(cfg: DuelConfig, v: Any): string[] {
  return [
    ...checkMeta(cfg, v),
    ...checkSchedules(cfg, v),
    ...checkDamage(cfg, v),
    ...checkRounds(cfg, v),
    ...checkMatches(cfg, v),
  ];
}
